import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        long[] values = {1, 10, 100, 1000, 10000};
        final long NEG = Long.MIN_VALUE / 4;
        // dp[h][used]: best suffix total where h - 1 is the highest grade to the right (0 = none).
        long[][] dp = new long[6][2];
        for (long[] row : dp) row[0] = row[1] = NEG;
        dp[0][0] = 0;
        for (int p = s.length() - 1; p >= 0; p--) {
            int original = s.charAt(p) - 'A';
            long[][] next = new long[6][2];
            for (long[] row : next) row[0] = row[1] = NEG;
            for (int h = 0; h < 6; h++)
                for (int used = 0; used < 2; used++) {
                    if (dp[h][used] == NEG) continue;
                    int highest = h - 1;
                    for (int c = 0; c < 5; c++) {
                        int changed = used + (c != original ? 1 : 0);
                        if (changed > 1) continue;
                        long candidate = dp[h][used] + (c >= highest ? values[c] : -values[c]);
                        int slot = Math.max(highest, c) + 1;
                        next[slot][changed] = Math.max(next[slot][changed], candidate);
                    }
                }
            dp = next;
        }
        long answer = NEG;
        for (long[] row : dp) answer = Math.max(answer, Math.max(row[0], row[1]));
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"math"
	"os"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	s := bytes.TrimSpace(data)
	values := [5]int64{1, 10, 100, 1000, 10000}
	const neg = math.MinInt64 / 4
	// dp[h][used]: best suffix total where h-1 is the highest grade to the right (0 = none).
	var dp [6][2]int64
	for h := range dp {
		dp[h] = [2]int64{neg, neg}
	}
	dp[0][0] = 0
	for p := len(s) - 1; p >= 0; p-- {
		original := int(s[p] - 'A')
		var next [6][2]int64
		for h := range next {
			next[h] = [2]int64{neg, neg}
		}
		for h := 0; h < 6; h++ {
			for used := 0; used < 2; used++ {
				if dp[h][used] == neg {
					continue
				}
				highest := h - 1
				for c := 0; c < 5; c++ {
					changed := used
					if c != original {
						changed++
					}
					if changed > 1 {
						continue
					}
					candidate := dp[h][used] - values[c]
					if c >= highest {
						candidate = dp[h][used] + values[c]
					}
					slot := max(highest, c) + 1
					next[slot][changed] = max(next[slot][changed], candidate)
				}
			}
		}
		dp = next
	}
	answer := int64(neg)
	for _, row := range dp {
		answer = max(answer, row[0], row[1])
	}
	fmt.Println(answer)
}
